if !ctx.IsCheckTx() {
	priority := getTxPriority(feeCoins, int64(gas)) //#nosec G701 -- gosec warning about integer overflow is not relevant here
	return feeCoins, priority, nil
}

minGasPrices := ctx.MinGasPrices()
if minGasPrices.IsZero() {
	priority := getTxPriority(feeCoins, int64(gas)) //#nosec G701 -- gosec warning about integer overflow is not relevant here
